<?php
namespace Tests\Feature;
use App\Models\Department; use App\Models\Employee; use App\Models\Shift; use App\Models\ShiftSchedule; use Illuminate\Database\QueryException; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Support\Facades\Hash; use Tests\TestCase;
class ShiftScheduleConstraintTest extends TestCase { use RefreshDatabase; public function test_employee_cannot_have_two_schedules_on_same_work_date(): void { $department=Department::create(['code'=>'PRD','name'=>'Produksi','is_active'=>true]); $employee=Employee::create(['nip'=>'EMP001','name'=>'Pegawai 1','department_id'=>$department->id,'employment_status'=>'active','attendance_pin_hash'=>Hash::make('123456'),'is_active'=>true]); $shift=Shift::create(['code'=>'SHIFT-1','name'=>'Shift 1','start_time'=>'07:00','end_time'=>'15:00','crosses_midnight'=>false,'is_active'=>true]); ShiftSchedule::create(['employee_id'=>$employee->id,'shift_id'=>$shift->id,'work_date'=>'2026-10-02']); $this->expectException(QueryException::class); ShiftSchedule::create(['employee_id'=>$employee->id,'shift_id'=>$shift->id,'work_date'=>'2026-10-02']); } }
